style.css:
input[type="checkbox"] {
    width: 20px; 
    background-color: #1a1a1a; 
    border: 2px solid #ff0000; 
    border-radius: 5px; 
    cursor: pointer;
}


input[type="checkbox"]:checked {
    background-color: #00ff00; 
    border-color: #00cc00;
}

input[type="checkbox"]:checked::before {
    content: "✔";
    color: blue;
    font-size: 16px;
    position: absolute;
    left: 3px;
    top: -1px;
}
